def peak(intervals):
    events=[]
    for start,end in intervals:
        if end<start: raise ValueError('interval')
        if end>start: events.extend([(start,1),(end,-1)])
    active=best=0
    for _,delta in sorted(events): active+=delta; best=max(best,active)
    return best

